    {"id": "MOTOR_BREMSE:lernpause","thema": "Gespräch über: Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Sorge: Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","beitraege": [{"text": "Was hilft beim Neustart? Wir vergleichen die Erfahrungen nach der Pause.","motor": true,"info": "Die Nachfrage prüft die Gründe und bezieht andere ein.","warum": [{"text": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","ok": true},{"text": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest.","ok": false},{"text": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail.","ok": false}]},{"text": "Wir zeigen das Ende an und nennen die nächste kurze Teilaufgabe.","motor": true,"info": "Der Vorschlag antwortet auf die geäußerte Sorge.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wer nach der Bewegungspause noch unruhig ist, hat beim Planen keine Stimme.","motor": false,"info": "Die Äußerung schließt andere von der Prüfung aus."},{"text": "Wir könnten für die Pause zunächst die beliebtesten Musikrichtungen sammeln.","motor": false,"info": "Diese Äußerung weicht von der strittigen Sache ab."}]}
